        Err(TscClientError::VersionCheckFailed { .. }) => {}
        Err(other) => panic!("expected VersionCheckFailed, got {other:?}"),
        Ok(_) => panic!("expected VersionCheckFailed, but spawn succeeded"),
    }
}
